import numpy as np

# Function f(A) = (2A+1)^3 / (3A)
def f(A):
    if A <= 0:
        return float('inf')
    return (2*A + 1)**3 / (3*A)

# Check the value at A = 1/4
A0 = 1/4
U_candidate = f(A0)
print(f"f(1/4): {U_candidate}")

# Function to find the root of g(A) = 16A^3 + 12A^2 - 1 = 0
def g(A):
    return 16*A**3 + 12*A**2 - 1

# Check the root A=1/4
print(f"g(1/4): {g(1/4)}")

# Check the derivative f'(A) at A=1/4
# f'(A) = 16/3 * A + 4 - 1/(3A^2)
def f_prime(A):
    if A <= 0:
        return float('inf')
    return (16/3)*A + 4 - 1/(3*A**2)

f_prime_A0 = f_prime(A0)
print(f"f'(1/4): {f_prime_A0}")
